mapper.select:
select
    count(1) as answer_count,
    count(*) filter (where answer_status = 'REVIEWED') as reviewed_answer_count,
    avg(total_score) filter (where answer_status = 'REVIEWED') as average_total_score
from user_answers
where user_id = #{userId}
  and learning_mode = #{learningMode}
  and deleted = false
  and question_id is not null
  and created_at >= #{startAt}
  and created_at < #{endAt}

select
    count(1) as answer_count,
    count(*) filter (where answer_status = 'REVIEWED') as reviewed_answer_count,
    avg(total_score) filter (where answer_status = 'REVIEWED') as average_total_score
from user_answers
where user_id = #{userId}
  and learning_mode = #{learningMode}
  and deleted = false
  and question_id is null
  and created_at >= #{startAt}
  and created_at < #{endAt}

select count(1)
from user_answer_errors answer_error
inner join user_answers user_answer
    on user_answer.id = answer_error.user_answer_id
   and user_answer.user_id = #{userId}
   and user_answer.deleted = false
   and user_answer.learning_mode = #{learningMode}
where answer_error.user_id = #{userId}
  and answer_error.created_at >= #{startAt}
  and answer_error.created_at < #{endAt}

select
    created_at::date as day,
    count(1) as answer_count,
    avg(total_score) filter (where answer_status = 'REVIEWED') as average_total_score
from user_answers
where user_id = #{userId}
  and learning_mode = #{learningMode}
  and deleted = false
  and question_id is not null
  and created_at >= #{startAt}
  and created_at < #{endAt}
group by created_at::date
order by day

select
    created_at::date as day,
    count(1) as answer_count,
    avg(total_score) filter (where answer_status = 'REVIEWED') as average_total_score
from user_answers
where user_id = #{userId}
  and learning_mode = #{learningMode}
  and deleted = false
  and question_id is null
  and created_at >= #{startAt}
  and created_at < #{endAt}
group by created_at::date
order by day

select
    avg(grammar_vocabulary_score) as grammar_vocabulary_score,
    avg(natural_fluency_score) as natural_fluency_score,
    avg(scenario_adaptation_score) as scenario_adaptation_score,
    avg(information_completeness_score) as information_completeness_score
from user_answers
where user_id = #{userId}
  and learning_mode = #{learningMode}
  and deleted = false
  and question_id is not null
  and answer_status = 'REVIEWED'
  and created_at >= #{startAt}
  and created_at < #{endAt}

select
    avg(grammar_vocabulary_score) as grammar_vocabulary_score,
    avg(natural_fluency_score) as natural_fluency_score,
    avg(scenario_adaptation_score) as scenario_adaptation_score,
    avg(information_completeness_score) as information_completeness_score
from user_answers
where user_id = #{userId}
  and learning_mode = #{learningMode}
  and deleted = false
  and question_id is null
  and answer_status = 'REVIEWED'
  and created_at >= #{startAt}
  and created_at < #{endAt}

select
    count(1) as review_attempt_count,
    count(*) filter (where review_attempt.result = 'PASS') as review_pass_count
from review_attempts review_attempt
inner join review_cards review_card on review_card.id = review_attempt.review_card_id
inner join user_error_types user_error_type on user_error_type.id = review_card.user_error_type_id
where review_attempt.user_id = #{userId}
  and user_error_type.learning_mode = #{learningMode}
  and review_attempt.attempt_source = 'REVIEW'
  and review_attempt.created_at >= #{startAt}
  and review_attempt.created_at < #{endAt}

select count(1)
from review_cycles review_cycle
inner join review_cards review_card
    on review_card.id = review_cycle.review_card_id
   and review_card.user_id = #{userId}
inner join user_error_types user_error_type
    on user_error_type.id = review_card.user_error_type_id
   and user_error_type.learning_mode = #{learningMode}
where review_cycle.status = 'COMPLETED'
  and review_cycle.completed_at >= #{startAt}
  and review_cycle.completed_at < #{endAt}
